ALTER TABLE socios ADD COLUMN IF NOT EXISTS nro_movil VARCHAR(20);

ON CONFLICT (id) DO UPDATE 
SET nro_movil = EXCLUDED.nro_movil,
    nombres = EXCLUDED.nombres,
    ap_paterno = EXCLUDED.ap_paterno,
    ap_materno = EXCLUDED.ap_materno,
    ci = EXCLUDED.ci,
    celular = EXCLUDED.celular,
    fecha_ingreso = EXCLUDED.fecha_ingreso,
    estado = EXCLUDED.estado,
    categoria = EXCLUDED.categoria,
    observaciones = EXCLUDED.observaciones;

SELECT setval('socios_id_seq', (SELECT GREATEST(MAX(id), 1) FROM socios));